import com.refinedmods.refinedstorage.api.storage.cache.IStorageCache;
import com.refinedmods.refinedstorage.api.util.Action;
import com.refinedmods.refinedstorage.api.util.IComparer;
import com.refinedmods.refinedstorage.api.util.StackListEntry;
import com.refinedmods.refinedstorage.apiimpl.API;
import com.refinedmods.refinedstorage.apiimpl.autocrafting.preview.ErrorCraftingPreviewElement;
import com.refinedmods.refinedstorage.container.GridContainerMenu;
import com.refinedmods.refinedstorage.network.grid.GridCraftingPreviewResponseMessage;
import com.refinedmods.refinedstorage.network.grid.GridCraftingStartResponseMessage;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.items.IItemHandler;
import net.neoforged.neoforge.items.ItemHandlerHelper;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import java.util.Collections;
import java.util.Optional;
import java.util.UUID;

public class ItemGridHandler implements IItemGridHandler {
    private final INetwork network;

    public ItemGridHandler(INetwork network) {
        this.network = network;
    }

    public static void onInventoryScroll(IItemGridHandler gridHandler, ServerPlayer player, int slot, boolean shift, boolean up, @Nullable INetwork network) {
        if (player == null || !(player.containerMenu instanceof GridContainerMenu)) {
            return;
        }

        if (network != null && ((up && !network.getSecurityManager().hasPermission(Permission.INSERT, player)) || (!up && !network.getSecurityManager().hasPermission(Permission.EXTRACT, player)))) {
            return;
        }

        int flags = EXTRACT_SINGLE;
        ItemStack stackInSlot = player.getInventory().getItem(slot);
        ItemStack stackOnCursor = player.containerMenu.getCarried();

        if (shift) { // shift
            flags |= EXTRACT_SHIFT;

            if (!stackInSlot.isEmpty()) {
                if (up) { // scroll up
                    player.getInventory().setItem(slot, gridHandler.onInsert(player, stackInSlot, true));
                } else { // scroll down
                    gridHandler.onExtract(player, stackInSlot, slot, flags);
                }
            }
        } else { //ctrl
            if (up) { // scroll up
                if (!stackOnCursor.isEmpty()) {
                    gridHandler.onInsert(player, stackOnCursor, true);
                }
            } else { //scroll down
                if (stackOnCursor.isEmpty()) {
                    gridHandler.onExtract(player, stackInSlot, -1, flags);
                } else {
                    gridHandler.onExtract(player, stackOnCursor, -1, flags);
                }
            }
        }
    }

    public static void onGridScroll(IItemGridHandler gridHandler, ServerPlayer player, @Nullable UUID id, boolean shift, boolean up, @Nullable INetwork network) {
        if (player == null || !(player.containerMenu instanceof GridContainerMenu)) {
            return;
        }

        if (network != null && ((up && !network.getSecurityManager().hasPermission(Permission.INSERT, player)) || (!up && !network.getSecurityManager().hasPermission(Permission.EXTRACT, player)))) {
            return;
        }

        IGrid grid = ((GridContainerMenu) player.containerMenu).getGrid();

        int flags = EXTRACT_SINGLE;

        if (shift && id != null) {
            flags |= EXTRACT_SHIFT;
            if (up) { //scroll up, insert hovering stack pulled from Inventory
                IStorageCache<ItemStack> cache = grid.getStorageCache();
                if (cache == null || cache.getList().get(id) == null) {
                    return;
                }

                for (int i = 0; i < player.getInventory().items.size(); i++) {
                    if (API.instance().getComparer().isEqual(player.getInventory().getItem(i), cache.getList().get(id), IComparer.COMPARE_NBT)) {
                        gridHandler.onInsert(player, player.getInventory().getItem(i), true);
                        break;
                    }
                }

            } else { //scroll down, extract hovering item
                gridHandler.onExtract(player, id, -1, flags);
            }
        } else { //ctrl
            if (!up && id != null) { //scroll down, extract hovering item
                gridHandler.onExtract(player, id, -1, flags);

            } else if (up && !player.containerMenu.getCarried().isEmpty()) { // insert stack from cursor
                gridHandler.onInsert(player, player.containerMenu.getCarried(), true);
            }
        }
    }

    @Override
    public void onExtract(ServerPlayer player, ItemStack stack, int preferredSlot, int flags) {
        StackListEntry<ItemStack> stackEntry = network.getItemStorageCache().getList().getEntry(stack, IComparer.COMPARE_NBT);
        if (stackEntry != null) {
            onExtract(player, stackEntry.getId(), preferredSlot, flags);
        }
    }

    @Override
    public void onExtract(ServerPlayer player, UUID id, int preferredSlot, int flags) {
        ItemStack item = network.getItemStorageCache().getList().get(id);

        if (item == null || !network.getSecurityManager().hasPermission(Permission.EXTRACT, player) || !network.canRun()) {
            return;
        }

        int itemSize = item.getCount();
        // We copy here because some mods change the NBT tag of an item after getting the stack limit
        int maxItemSize = item.getItem().getMaxStackSize(item.copy());

        boolean single = (flags & EXTRACT_SINGLE) == EXTRACT_SINGLE;

        ItemStack held = player.containerMenu.getCarried();

        if (single) {
            if (!held.isEmpty() && (!API.instance().getComparer().isEqualNoQuantity(item, held) || held.getCount() + 1 > held.getMaxStackSize())) {
                return;
            }
        } else if (!player.containerMenu.getCarried().isEmpty()) {
            return;
        }

        int size = 64;

        if ((flags & EXTRACT_HALF) == EXTRACT_HALF && itemSize > 1) {
            size = itemSize / 2;

            // Rationale for this check:
            // If we have 32 buckets, and we want to extract half, we expect/need to get 8 (max stack size 16 / 2).
            // Without this check, we would get 16 (total stack size 32 / 2).
            // Max item size also can't be 1. Otherwise, if we want to extract half of 8 lava buckets, we would get size 0 (1 / 2).
            if (size > maxItemSize / 2 && maxItemSize != 1) {
                size = maxItemSize / 2;
            }
        } else if (single) {
            size = 1;
        } else if ((flags & EXTRACT_SHIFT) == EXTRACT_SHIFT) {
            // NO OP, the quantity already set (64) is needed for shift
        }

        size = Math.min(size, maxItemSize);

        // Do this before actually extracting, since external storage sends updates as soon as a change happens (so before the storage tracker used to track)
        network.getItemStorageTracker().changed(player, item.copy());

        ItemStack took = network.extractItem(item, size, Action.SIMULATE);

        if (!took.isEmpty()) {
            if ((flags & EXTRACT_SHIFT) == EXTRACT_SHIFT) {
                IItemHandler playerInventory = player.getCapability(Capabilities.ItemHandler.ENTITY);
                if (playerInventory != null) {
                    if (preferredSlot != -1) {
                        ItemStack remainder = playerInventory.insertItem(preferredSlot, took, true);
                        if (remainder.getCount() != took.getCount()) {
                            ItemStack inserted = network.extractItem(item, size - remainder.getCount(), Action.PERFORM);
                            playerInventory.insertItem(preferredSlot, inserted, false);
                            took.setCount(remainder.getCount());
                        }
                    }

                    if (!took.isEmpty() && ItemHandlerHelper.insertItemStacked(playerInventory, took, true).isEmpty()) {
                        took = network.extractItem(item, size, Action.PERFORM);

                        ItemHandlerHelper.insertItemStacked(playerInventory, took, false);
                    }
                }
            } else {
                took = network.extractItem(item, size, Action.PERFORM);

                if (!took.isEmpty()) {
                    if (single && !held.isEmpty()) {
                        held.grow(1);
                    } else {
                        player.containerMenu.setCarried(took);
                    }
                }
            }

            network.getNetworkItemManager().drainEnergy(player, RS.SERVER_CONFIG.getWirelessGrid().getExtractUsage());
        }
    }

    @Override
    @Nonnull
    public ItemStack onInsert(ServerPlayer player, ItemStack stack, boolean single) {
        if (!network.getSecurityManager().hasPermission(Permission.INSERT, player) || !network.canRun()) {
            return stack;
        }

        network.getItemStorageTracker().changed(player, stack.copy());

        ItemStack remainder;
        if (single) {
            if (network.insertItem(stack, 1, Action.SIMULATE).isEmpty()) {
                network.insertItem(stack, 1, Action.PERFORM);
                stack.shrink(1);
            }
            remainder = stack;
        } else {
            remainder = network.insertItem(stack, stack.getCount(), Action.PERFORM);
        }

        network.getNetworkItemManager().drainEnergy(player, RS.SERVER_CONFIG.getWirelessGrid().getInsertUsage());

        return remainder;
    }

    @Override
    public void onInsertHeldItem(ServerPlayer player, boolean single) {
        if (player.containerMenu.getCarried().isEmpty() || !network.getSecurityManager().hasPermission(Permission.INSERT, player) || !network.canRun()) {
            return;
        }

        ItemStack stack = player.containerMenu.getCarried();
        int size = single ? 1 : stack.getCount();

        network.getItemStorageTracker().changed(player, stack.copy());

        if (single) {
            if (network.insertItem(stack, size, Action.SIMULATE).isEmpty()) {
                network.insertItem(stack, size, Action.PERFORM);

                stack.shrink(size);
            }
        } else {
            player.containerMenu.setCarried(network.insertItem(stack, size, Action.PERFORM));
        }

        network.getNetworkItemManager().drainEnergy(player, RS.SERVER_CONFIG.getWirelessGrid().getInsertUsage());
    }

    @Override
    public void onCraftingPreviewRequested(ServerPlayer player, UUID id, int quantity, boolean noPreview) {
        if (!network.getSecurityManager().hasPermission(Permission.AUTOCRAFTING, player)) {
            return;
        }

        ItemStack stack = network.getItemStorageCache().getCraftablesList().get(id);

        if (stack != null) {
            ICalculationResult result = network.getCraftingManager().create(stack, quantity);

            if (!result.isOk() && result.getType() != CalculationResultType.MISSING) {
                RS.NETWORK_HANDLER.sendTo(
                    player,
                    new GridCraftingPreviewResponseMessage(
                        Collections.singletonList(new ErrorCraftingPreviewElement(result.getType(), result.getRecursedPattern() == null ? ItemStack.EMPTY : result.getRecursedPattern().getStack())),
                        id,
                        quantity,
                        false
                    )
                );
            } else if (result.isOk() && noPreview) {
                network.getCraftingManager().start(result.getTask());

                RS.NETWORK_HANDLER.sendTo(player, new GridCraftingStartResponseMessage());
            } else {
                RS.NETWORK_HANDLER.sendTo(
                    player,
                    new GridCraftingPreviewResponseMessage(
                        result.getPreviewElements(),
                        id,
                        quantity,
                        false
                    )
                );
            }
        }
    }

    @Override
    public void onCraftingRequested(ServerPlayer player, UUID id, int quantity) {
        if (quantity <= 0 || !network.getSecurityManager().hasPermission(Permission.AUTOCRAFTING, player)) {
            return;
        }

        ItemStack stack = network.getItemStorageCache().getCraftablesList().get(id);

        if (stack != null) {
            ICalculationResult result = network.getCraftingManager().create(stack, quantity);
            if (result.isOk()) {
                network.getCraftingManager().start(result.getTask());
            }
        }
    }

    @Override
    public void onCraftingCancelRequested(ServerPlayer player, @Nullable UUID id) {
        if (!network.getSecurityManager().hasPermission(Permission.AUTOCRAFTING, player)) {
            return;
        }

        network.getCraftingManager().cancel(id);

        network.getNetworkItemManager().drainEnergy(player, id == null ? RS.SERVER_CONFIG.getWirelessCraftingMonitor().getCancelAllUsage() : RS.SERVER_CONFIG.getWirelessCraftingMonitor().getCancelUsage());
    }

    @Override
    public void onInventoryScroll(ServerPlayer player, int slot, boolean shift, boolean up) {
        onInventoryScroll(this, player, slot, shift, up, network);
    }

    @Override
    public void onGridScroll(ServerPlayer player, @Nullable UUID id, boolean shift, boolean up) {
        onGridScroll(this, player, id, shift, up, network);
    }
}

package com.refinedmods.refinedstorage.apiimpl.network.node.cover;

import com.refinedmods.refinedstorage.api.util.Action;
import com.refinedmods.refinedstorage.apiimpl.network.node.CableNetworkNode;
import com.refinedmods.refinedstorage.apiimpl.network.node.NetworkNode;
import com.refinedmods.refinedstorage.item.CoverItem;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.client.model.data.ModelProperty;
import net.neoforged.neoforge.items.IItemHandlerModifiable;
import net.neoforged.neoforge.items.ItemStackHandler;
import javax.annotation.Nullable;
import java.util.HashMap;
import java.util.Map;

public class CoverManager {

    public static final ModelProperty<CoverManager> PROPERTY = new ModelProperty<>();
    private static final String NBT_DIRECTION = "Direction";
    private static final String NBT_ITEM = "Item";
    private static final String NBT_TYPE = "Type";
    public static String NBT_COVER_MANAGER = "Cover";
    private Map<Direction, Cover> covers = new HashMap<>();
    private NetworkNode node;

    public CoverManager(NetworkNode node) {
        this.node = node;
    }

    @SuppressWarnings("deprecation")
    public static boolean isValidCover(ItemStack item) {
        if (item.isEmpty()) {
            return false;
        }

        Block block = getBlock(item);

        BlockState state = getBlockState(item);

        return block != null
            && state != null
            && isModelSupported(state)
            && !block.isRandomlyTicking(state)
            && !(block instanceof EntityBlock)
            && !state.useShapeForLightOcclusion();
    }

    private static boolean isModelSupported(BlockState state) {
        if (state.getRenderShape() != RenderShape.MODEL) {
            return false;
        }

        return state.canOcclude();
    }

    @Nullable
    public static Block getBlock(ItemStack item) {
        if (item.isEmpty()) {
            return null;
        }

        Block block = Block.byItem(item.getItem());

        if (block == Blocks.AIR) {
            return null;
        }

        return block;
    }

    @Nullable
    public static BlockState getBlockState(ItemStack item) {
        Block block = getBlock(item);
        if (block == null) {
            return null;
        }
        return block.defaultBlockState();
    }

    @Nullable
    public Cover getCover(Direction facing) {
        return covers.get(facing);
    }

    public boolean hasCover(Direction facing) {
        return covers.containsKey(facing);
    }

    public boolean setCover(Direction facing, @Nullable Cover cover) {
        if (cover == null || (isValidCover(cover.getStack()) && !hasCover(facing))) {
            if (cover != null) {
                if (!(node instanceof CableNetworkNode) && facing == node.getDirection() && cover.getType() != CoverType.HOLLOW) {
                    return false;
                }
            }

            if (cover == null) {
                covers.remove(facing);
            } else {
                covers.put(facing, cover);
            }

            node.markDirty();

            if (node.getNetwork() != null) {
                node.getNetwork().getNodeGraph().invalidate(Action.PERFORM, node.getNetwork().getLevel(), node.getNetwork().getPosition());
            }

            return true;
        }

        return false;
    }

    @Nullable
    public Cover removeCover(Direction direction) {
        if (hasCover(direction)) {
            Cover cover = covers.remove(direction);

            node.markDirty();

            if (node.getNetwork() != null) {
                node.getNetwork().getNodeGraph().invalidate(Action.PERFORM, node.getNetwork().getLevel(), node.getNetwork().getPosition());
            }

            return cover;
        }
        return null;
    }

    public void readFromNbt(CompoundTag nbt) {
        covers.clear();
        for (String s : nbt.getAllKeys()) {
            CompoundTag tag = nbt.getCompound(s);
            if (tag.contains(NBT_DIRECTION) && tag.contains(NBT_ITEM)) {
                Direction direction = Direction.from3DDataValue(tag.getInt(NBT_DIRECTION));
                ItemStack item = ItemStack.of(tag.getCompound(NBT_ITEM));
                int type = tag.contains(NBT_TYPE) ? tag.getInt(NBT_TYPE) : 0;

                if (type >= CoverType.values().length) {
                    type = 0;
                }

                if (isValidCover(item)) {
                    covers.put(direction, new Cover(item, CoverType.values()[type]));
                }
            }
        }
    }

    public CompoundTag writeToNbt() {
        CompoundTag list = new CompoundTag();

        for (Map.Entry<Direction, Cover> entry : covers.entrySet()) {
            CompoundTag tag = new CompoundTag();

            tag.putInt(NBT_DIRECTION, entry.getKey().ordinal());
            tag.put(NBT_ITEM, entry.getValue().getStack().save(new CompoundTag()));
            tag.putInt(NBT_TYPE, entry.getValue().getType().ordinal());

            list.put(entry.getKey().ordinal() + "", tag);
        }
        return list;
    }

    public IItemHandlerModifiable getAsInventory() {
        ItemStackHandler handler = new ItemStackHandler(covers.size());

        int i = 0;

        for (Map.Entry<Direction, Cover> entry : covers.entrySet()) {
            ItemStack cover = entry.getValue().getType().createStack();

            CoverItem.setItem(cover, entry.getValue().getStack());

            handler.setStackInSlot(i++, cover);
        }

        return handler;
    }

}

package com.refinedmods.refinedstorage.apiimpl.storage.tracker;

import com.refinedmods.refinedstorage.api.storage.tracker.IStorageTracker;
import com.refinedmods.refinedstorage.api.storage.tracker.StorageTrackerEntry;
import com.refinedmods.refinedstorage.api.util.IComparer;
import com.refinedmods.refinedstorage.apiimpl.API;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.fluids.FluidStack;
import java.util.HashMap;
import java.util.Map;

public class FluidStorageTracker implements IStorageTracker<FluidStack> {
    private static final String NBT_STACK = "Stack";
    private static final String NBT_NAME = "Name";
    private static final String NBT_TIME = "Time";

    private final Map<Key, StorageTrackerEntry> changes = new HashMap<>();
    private final Runnable listener;

    public FluidStorageTracker(Runnable listener) {
        this.listener = listener;
    }

    @Override
    public void changed(Player player, FluidStack stack) {
        changes.put(new Key(stack), new StorageTrackerEntry(System.currentTimeMillis(), player.getName().getString()));

        listener.run();
    }

    @Override
    public StorageTrackerEntry get(FluidStack stack) {
        return changes.get(new Key(stack));
    }

    @Override
    public void readFromNbt(ListTag list) {
        for (int i = 0; i < list.size(); ++i) {
            CompoundTag tag = list.getCompound(i);

            FluidStack stack = FluidStack.loadFluidStackFromNBT(tag.getCompound(NBT_STACK));

            if (!stack.isEmpty()) {
                changes.put(new Key(stack), new StorageTrackerEntry(tag.getLong(NBT_TIME), tag.getString(NBT_NAME)));
            }
        }
    }

    @Override
    public ListTag serializeNbt() {
        ListTag list = new ListTag();

        for (Map.Entry<Key, StorageTrackerEntry> entry : changes.entrySet()) {
            CompoundTag tag = new CompoundTag();

            tag.putLong(NBT_TIME, entry.getValue().getTime());
            tag.putString(NBT_NAME, entry.getValue().getName());
            tag.put(NBT_STACK, entry.getKey().stack.writeToNBT(new CompoundTag()));

            list.add(tag);
        }

        return list;
    }

    private static class Key {
        private final FluidStack stack;

        public Key(FluidStack stack) {
            this.stack = stack;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof Key && API.instance().getComparer().isEqual(stack, ((Key) other).stack, IComparer.COMPARE_NBT);
        }

        @Override
        public int hashCode() {
            return API.instance().getFluidStackHashCode(stack);
        }
    }
}

package com.refinedmods.refinedstorage.apiimpl.storage.tracker;

import com.refinedmods.refinedstorage.api.storage.tracker.IStorageTracker;
import com.refinedmods.refinedstorage.api.storage.tracker.StorageTrackerEntry;
import com.refinedmods.refinedstorage.util.ItemStackKey;
import com.refinedmods.refinedstorage.util.StackUtils;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

import java.util.HashMap;
import java.util.Map;

public class ItemStorageTracker implements IStorageTracker<ItemStack> {
    private static final String NBT_STACK = "Stack";
    private static final String NBT_NAME = "Name";
    private static final String NBT_TIME = "Time";

    private final Map<ItemStackKey, StorageTrackerEntry> changes = new HashMap<>();
    private final Runnable listener;

    public ItemStorageTracker(Runnable listener) {
        this.listener = listener;
    }

    @Override
    public void changed(Player player, ItemStack stack) {
        changes.put(new ItemStackKey(stack), new StorageTrackerEntry(System.currentTimeMillis(), player.getName().getString()));

        listener.run();
    }

    @Override
    public StorageTrackerEntry get(ItemStack stack) {
        return changes.get(new ItemStackKey(stack));
    }

    @Override
    public void readFromNbt(ListTag list) {
        for (int i = 0; i < list.size(); ++i) {
            CompoundTag tag = list.getCompound(i);

            ItemStack stack = StackUtils.deserializeStackFromNbt(tag.getCompound(NBT_STACK));

            if (!stack.isEmpty()) {
                changes.put(new ItemStackKey(stack), new StorageTrackerEntry(tag.getLong(NBT_TIME), tag.getString(NBT_NAME)));
            }
        }
    }

    @Override
    public ListTag serializeNbt() {
        ListTag list = new ListTag();

        for (Map.Entry<ItemStackKey, StorageTrackerEntry> entry : changes.entrySet()) {
            CompoundTag tag = new CompoundTag();

            tag.putLong(NBT_TIME, entry.getValue().getTime());
            tag.putString(NBT_NAME, entry.getValue().getName());
            tag.put(NBT_STACK, StackUtils.serializeStackToNbt(entry.getKey().getStack()));

            list.add(tag);
        }

        return list;
    }
}

package com.refinedmods.refinedstorage.apiimpl.storage.tracker;

import com.refinedmods.refinedstorage.api.storage.StorageType;
import com.refinedmods.refinedstorage.api.storage.tracker.IStorageTracker;
import com.refinedmods.refinedstorage.api.storage.tracker.IStorageTrackerManager;
import com.refinedmods.refinedstorage.apiimpl.util.RSSavedData;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

public class StorageTrackerManager extends RSSavedData implements IStorageTrackerManager {
    public static final String NAME = "refinedstorage_tracker";

    private static final String NBT_TRACKERS = "Tracker";
    private static final String NBT_TRACKER_ID = "Id";
    private static final String NBT_TRACKER_DATA = "Data";
    private static final String NBT_TRACKER_TYPE = "Type";

    private final Map<UUID, IStorageTracker<?>> trackers = new HashMap<>();

    @Override
    public void markForSaving() {
        this.setDirty();
    }

    @Override
    public IStorageTracker<?> getOrCreate(UUID uuid, StorageType type) {
        IStorageTracker<?> tracker = trackers.get(uuid);

        if (tracker == null) {
            if (type == StorageType.ITEM) {
                tracker = new ItemStorageTracker(this::markForSaving);
            } else if (type == StorageType.FLUID) {
                tracker = new FluidStorageTracker(this::markForSaving);
            }

            trackers.put(uuid, tracker);
        }

        return tracker;
    }

    @Override
    public void remove(UUID id) {
        trackers.remove(id);
    }

    @Override
    public void load(CompoundTag nbt) {
        if (nbt.contains(NBT_TRACKERS)) {
            ListTag trackerTags = nbt.getList(NBT_TRACKERS, Tag.TAG_COMPOUND);

            for (int i = 0; i < trackerTags.size(); ++i) {
                CompoundTag trackerTag = trackerTags.getCompound(i);

                UUID id = trackerTag.getUUID(NBT_TRACKER_ID);
                ListTag data = trackerTag.getList(NBT_TRACKER_DATA, Tag.TAG_COMPOUND);
                StorageType type = StorageType.values()[trackerTag.getInt(NBT_TRACKER_TYPE)];

                IStorageTracker<?> tracker = getOrCreate(id, type);
                tracker.readFromNbt(data);
            }
        }
    }

    @Override
    public CompoundTag save(CompoundTag compound) {
        ListTag trackerListTag = new ListTag();

        for (Map.Entry<UUID, IStorageTracker<?>> entry : trackers.entrySet()) {
            CompoundTag trackerTag = new CompoundTag();

            trackerTag.putUUID(NBT_TRACKER_ID, entry.getKey());
            trackerTag.put(NBT_TRACKER_DATA, entry.getValue().serializeNbt());
            trackerTag.putInt(NBT_TRACKER_TYPE, entry.getValue() instanceof ItemStorageTracker ? StorageType.ITEM.ordinal() : StorageType.FLUID.ordinal());

            trackerListTag.add(trackerTag);
        }

        compound.put(NBT_TRACKERS, trackerListTag);

        return compound;
    }
}

package com.refinedmods.refinedstorage.inventory.fluid;

import com.refinedmods.refinedstorage.inventory.listener.InventoryListener;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.neoforge.fluids.FluidStack;
import javax.annotation.Nonnull;
import java.util.ArrayList;
import java.util.List;

public class FluidInventory {
    private static final String NBT_SLOT = "Slot_%d";

    private final List<InventoryListener<FluidInventory>> listeners = new ArrayList<>();

    private final FluidStack[] fluids;
    private final int maxAmount;
    private boolean empty = true;

    public FluidInventory(int size, int maxAmount) {
        this.fluids = new FluidStack[size];

        for (int i = 0; i < size; ++i) {
            fluids[i] = FluidStack.EMPTY;
        }

        this.maxAmount = maxAmount;
    }

    public FluidInventory(int size) {
        this(size, Integer.MAX_VALUE);
    }

    public FluidInventory addListener(InventoryListener<FluidInventory> listener) {
        listeners.add(listener);

        return this;
    }

    public int getSlots() {
        return fluids.length;
    }

    public int getMaxAmount() {
        return maxAmount;
    }

    public FluidStack[] getFluids() {
        return fluids;
    }

    @Nonnull
    public FluidStack getFluid(int slot) {
        return fluids[slot];
    }

    public void setFluid(int slot, @Nonnull FluidStack stack) {
        if (stack.getAmount() > maxAmount) {
            throw new IllegalArgumentException("Fluid size is invalid (given: " + stack.getAmount() + ", max size: " + maxAmount + ")");
        }

        fluids[slot] = stack;

        onChanged(slot);
    }

    public void onChanged(int slot) {
        listeners.forEach(l -> l.onChanged(this, slot, false));
        updateEmptyState();
    }

    public CompoundTag writeToNbt() {
        CompoundTag tag = new CompoundTag();

        for (int i = 0; i < getSlots(); ++i) {
            FluidStack stack = getFluid(i);

            if (!stack.isEmpty()) {
                tag.put(String.format(NBT_SLOT, i), stack.writeToNBT(new CompoundTag()));
            }
        }

        return tag;
    }

    public void readFromNbt(CompoundTag tag) {
        for (int i = 0; i < getSlots(); ++i) {
            String key = String.format(NBT_SLOT, i);

            if (tag.contains(key)) {
                fluids[i] = FluidStack.loadFluidStackFromNBT(tag.getCompound(key));
            }
        }

        updateEmptyState();
    }

    private void updateEmptyState() {
        this.empty = true;

        for (FluidStack fluid : fluids) {
            if (!fluid.isEmpty()) {
                this.empty = false;

                return;
            }
        }
    }

    public boolean isEmpty() {
        return empty;
    }
}

package com.refinedmods.refinedstorage.item;

import com.refinedmods.refinedstorage.RS;
import com.refinedmods.refinedstorage.api.network.INetwork;
import com.refinedmods.refinedstorage.api.network.node.ICoverable;
import com.refinedmods.refinedstorage.api.network.node.INetworkNode;
import com.refinedmods.refinedstorage.api.network.security.Permission;
import com.refinedmods.refinedstorage.apiimpl.network.node.cover.Cover;
import com.refinedmods.refinedstorage.util.NetworkUtils;
import com.refinedmods.refinedstorage.util.LevelUtils;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.items.ItemHandlerHelper;

public class WrenchItem extends Item {
    public WrenchItem() {
        super(new Item.Properties().stacksTo(1));
    }

    @Override
    public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext ctx) {
        if (ctx.getLevel().isClientSide) {
            return InteractionResult.CONSUME;
        }

        INetworkNode node = NetworkUtils.getNodeFromBlockEntity(ctx.getLevel().getBlockEntity(ctx.getClickedPos()));
        INetwork network = NetworkUtils.getNetworkFromNode(node);
        if (network != null && !network.getSecurityManager().hasPermission(Permission.BUILD, ctx.getPlayer())) {
            LevelUtils.sendNoPermissionMessage(ctx.getPlayer());

            return InteractionResult.FAIL;
        }
        BlockState state = ctx.getLevel().getBlockState(ctx.getClickedPos());

        if (node instanceof ICoverable && ((ICoverable) node).getCoverManager().hasCover(ctx.getClickedFace())) {
            Cover cover = ((ICoverable) node).getCoverManager().removeCover(ctx.getClickedFace());
            if (cover != null) {
                ItemStack stack1 = cover.getType().createStack();
                CoverItem.setItem(stack1, cover.getStack());
                ItemHandlerHelper.giveItemToPlayer(ctx.getPlayer(), stack1);
                ctx.getLevel().sendBlockUpdated(ctx.getClickedPos(), state, state, 3);
                ctx.getLevel().updateNeighborsAt(ctx.getClickedPos(), ctx.getLevel().getBlockState(ctx.getClickedPos()).getBlock());
                return InteractionResult.SUCCESS;
            }
        }

        ctx.getLevel().setBlockAndUpdate(ctx.getClickedPos(), state.rotate(ctx.getLevel(), ctx.getClickedPos(), Rotation.CLOCKWISE_90));

        return InteractionResult.CONSUME;
    }
}

